import { z } from 'zod';

// Base API envelope schema
export const ApiEnvelopeSchema = z.object({
  status: z.enum(['ok', 'error']),
  data: z.any().optional(),
  error: z.object({
    code: z.number(),
    message: z.string()
  }).optional()
});

// Health response schemas
export const HealthGateSchema = z.object({
  name: z.string(),
  status: z.enum(['ok', 'error', 'warning']),
  message: z.string().optional(),
  last_check: z.string().optional()
});

export const HealthResponseSchema = z.object({
  status: z.literal('ok'),
  data: z.object({
    all_gates_passed: z.boolean(),
    service: z.string(),
    gates: z.record(z.string(), HealthGateSchema),
    errors: z.array(z.string()),
    fallbacks_enabled: z.boolean(),
    embedding_model: z.string(),
    embedding_dim: z.number(),
    models_checksum: z.string(),
    pgvector: z.object({
      status: z.string(),
      connection: z.string()
    }),
    rulego: z.object({
      status: z.string(),
      policies: z.number()
    }),
    reverse_proxy: z.boolean(),
    ui_origin: z.string()
  })
});

// Models response schemas
export const ModelInfoSchema = z.object({
  provider: z.string(),
  name: z.string(),
  device: z.string(),
  extra: z.record(z.string(), z.any()).optional(),
  checksum: z.string().optional(),
  status: z.enum(['active', 'inactive', 'deprecated']).optional()
});

export const ModelsResponseSchema = z.object({
  status: z.literal('ok'),
  data: z.object({
    llm: ModelInfoSchema,
    embedding: ModelInfoSchema,
    ner: ModelInfoSchema.optional(),
    reranker: ModelInfoSchema.optional(),
    ocr: ModelInfoSchema.optional(),
    stt: ModelInfoSchema.optional(),
    diarization: ModelInfoSchema.optional(),
    topics: ModelInfoSchema.optional()
  })
});

// Runs response schemas
export const RunSchema = z.object({
  id: z.string(),
  status: z.enum(['running', 'completed', 'failed']),
  created_at: z.string(),
  updated_at: z.string(),
  source: z.string(),
  documents_count: z.number(),
  documents_processed: z.number(),
  error: z.string().optional()
});

export const RunsResponseSchema = z.object({
  status: z.literal('ok'),
  data: z.object({
    runs: z.array(RunSchema),
    total: z.number()
  })
});

export const RunDetailSchema = z.object({
  id: z.string(),
  status: z.enum(['running', 'completed', 'failed']),
  created_at: z.string(),
  updated_at: z.string(),
  source: z.string(),
  documents: z.array(z.object({
    id: z.string(),
    title: z.string(),
    url: z.string().optional(),
    content: z.string(),
    metadata: z.record(z.string(), z.any()).optional()
  })),
  manifest: z.object({
    version: z.string(),
    source: z.string(),
    documents_count: z.number(),
    created_at: z.string(),
    checksum: z.string()
  }).optional(),
  merkle: z.object({
    root: z.string(),
    leaves: z.array(z.string())
  }).optional(),
  metrics: z.object({
    total_documents: z.number(),
    processed_documents: z.number(),
    total_bytes: z.number(),
    processing_time_ms: z.number(),
    errors: z.array(z.string())
  }).optional()
});

export const RunDetailResponseSchema = z.object({
  status: z.literal('ok'),
  data: RunDetailSchema
});

// Start run request/response schemas
export const StartRunRequestSchema = z.object({
  channel_url: z.string().optional(),
  limit: z.number().optional(),
  sort: z.string().optional(),
  max_depth: z.number().optional(),
  ocr_required: z.boolean().optional(),
  js_render: z.boolean().optional(),
  hf_burst: z.boolean().optional(),
  run_label: z.string().optional(),
  save_to_directory: z.string().optional()
});

export const StartRunResponseSchema = z.object({
  status: z.literal('ok'),
  data: z.object({
    run_id: z.string(),
    status: z.enum(['running', 'completed', 'failed']),
    message: z.string()
  })
});

// Graph response schemas
export const GraphNodeSchema = z.object({
  id: z.string(),
  label: z.string(),
  type: z.string(),
  properties: z.record(z.string(), z.any()).optional()
});

export const GraphEdgeSchema = z.object({
  id: z.string(),
  source: z.string(),
  target: z.string(),
  label: z.string(),
  properties: z.record(z.string(), z.any()).optional()
});

export const GraphResponseSchema = z.object({
  status: z.literal('ok'),
  data: z.object({
    nodes: z.array(GraphNodeSchema),
    edges: z.array(GraphEdgeSchema),
    stats: z.object({
      total_nodes: z.number(),
      total_edges: z.number(),
      node_types: z.record(z.string(), z.number()),
      edge_types: z.record(z.string(), z.number())
    })
  })
});

// Claims and entities schemas
export const ClaimSchema = z.object({
  id: z.string(),
  text: z.string(),
  confidence: z.number(),
  source_document: z.string(),
  evidence: z.array(z.string()).optional(),
  created_at: z.string()
});

export const ClaimsResponseSchema = z.object({
  status: z.literal('ok'),
  data: z.object({
    claims: z.array(ClaimSchema),
    total: z.number(),
    page: z.number(),
    per_page: z.number()
  })
});

export const EntitySchema = z.object({
  id: z.string(),
  name: z.string(),
  type: z.string(),
  mentions: z.number(),
  documents: z.array(z.string()),
  properties: z.record(z.string(), z.any()).optional(),
  created_at: z.string()
});

export const EntitiesResponseSchema = z.object({
  status: z.literal('ok'),
  data: z.object({
    entities: z.array(EntitySchema),
    total: z.number(),
    page: z.number(),
    per_page: z.number()
  })
});

// Error response schema
export const ErrorResponseSchema = z.object({
  status: z.literal('error'),
  error: z.object({
    code: z.number(),
    message: z.string()
  })
});

// Type exports
export type ApiEnvelope = z.infer<typeof ApiEnvelopeSchema>;
export type HealthResponse = z.infer<typeof HealthResponseSchema>;
export type ModelsResponse = z.infer<typeof ModelsResponseSchema>;
export type RunsResponse = z.infer<typeof RunsResponseSchema>;
export type RunDetailResponse = z.infer<typeof RunDetailResponseSchema>;
export type StartRunRequest = z.infer<typeof StartRunRequestSchema>;
export type StartRunResponse = z.infer<typeof StartRunResponseSchema>;
export type GraphResponse = z.infer<typeof GraphResponseSchema>;
export type ClaimsResponse = z.infer<typeof ClaimsResponseSchema>;
export type EntitiesResponse = z.infer<typeof EntitiesResponseSchema>;
export type ErrorResponse = z.infer<typeof ErrorResponseSchema>;

// Validation functions
export function validateApiEnvelope(data: unknown): ApiEnvelope {
  return ApiEnvelopeSchema.parse(data);
}

export function validateHealthResponse(data: unknown): HealthResponse {
  return HealthResponseSchema.parse(data);
}

export function validateModelsResponse(data: unknown): ModelsResponse {
  return ModelsResponseSchema.parse(data);
}

export function validateRunsResponse(data: unknown): RunsResponse {
  return RunsResponseSchema.parse(data);
}

export function validateRunDetailResponse(data: unknown): RunDetailResponse {
  return RunDetailResponseSchema.parse(data);
}

export function validateStartRunRequest(data: unknown): StartRunRequest {
  return StartRunRequestSchema.parse(data);
}

export function validateStartRunResponse(data: unknown): StartRunResponse {
  return StartRunResponseSchema.parse(data);
}

export function validateGraphResponse(data: unknown): GraphResponse {
  return GraphResponseSchema.parse(data);
}

export function validateClaimsResponse(data: unknown): ClaimsResponse {
  return ClaimsResponseSchema.parse(data);
}

export function validateEntitiesResponse(data: unknown): EntitiesResponse {
  return EntitiesResponseSchema.parse(data);
}

export function validateErrorResponse(data: unknown): ErrorResponse {
  return ErrorResponseSchema.parse(data);
}
