import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { ReactQueryDevtools } from '@tanstack/react-query-devtools';
import { useState, type ReactNode } from 'react';
import { getHealth, getModels, getRun, getRunCorpus, getRuns } from './api';

// Query client configuration
export function createQueryClient() {
  return new QueryClient({
    defaultOptions: {
      queries: {
        staleTime: 5 * 60 * 1000,
        gcTime: 10 * 60 * 1000,
        retry: (failureCount, error) => {
          if (error instanceof Error && 'status' in error && (error as { status: number }).status >= 400 && (error as { status: number }).status < 500) {
            return false;
          }
          return failureCount < 3;
        },
        refetchOnWindowFocus: false,
      },
      mutations: {
        retry: false,
      },
    },
  });
}

// Query provider component
export function QueryProvider({ children }: { children: ReactNode }) {
  const [queryClient] = useState(() => createQueryClient());

  return (
    <QueryClientProvider client={queryClient}>
      {children}
      <ReactQueryDevtools initialIsOpen={false} />
    </QueryClientProvider>
  );
}

// Query keys
export const queryKeys = {
  health: ['health'] as const,
  healthFull: ['health', 'full'] as const,
  models: ['models'] as const,
  runs: ['runs'] as const,
  run: (id: string) => ['runs', id] as const,
  runCorpus: (id: string) => ['runs', id, 'corpus'] as const,
} as const;

// Health query hook - basic health check
export function useHealth() {
  return {
    queryKey: queryKeys.health,
    queryFn: async () => {
      const response = await fetch('http://localhost:8050/api/health');
      return response.json();
    },
  };
}

// Health full query hook - detailed health check
export function useHealthFull() {
  return {
    queryKey: queryKeys.healthFull,
    queryFn: getHealth, // This calls /api/health/full
  };
}

// Models query hook
export function useModels() {
  return {
    queryKey: queryKeys.models,
    queryFn: getModels,
  };
}

// Runs list query hook
export function useRuns() {
  return {
    queryKey: queryKeys.runs,
    queryFn: getRuns,
  };
}

// Run detail query hook
export function useRun(id: string) {
  return {
    queryKey: queryKeys.run(id),
    queryFn: () => getRun(id),
    enabled: !!id,
  };
}

// Run corpus query hook
export function useRunCorpus(id: string) {
  return {
    queryKey: queryKeys.runCorpus(id),
    queryFn: () => getRunCorpus(id),
    enabled: !!id,
  };
}
